import { test } from 'node:test';
import assert from 'node:assert/strict';
import { RATING_SCALE, notchChange } from '../../src/ratings/notch.mjs';

// AC-1: RATING_SCALE structure
test('AC-1: RATING_SCALE is an array of 19 ratings', () => {
  assert.strictEqual(Array.isArray(RATING_SCALE), true);
  assert.strictEqual(RATING_SCALE.length, 19);
  assert.deepStrictEqual(RATING_SCALE, ['AAA', 'AA+', 'AA', 'AA-', 'A+', 'A', 'A-', 'BBB+', 'BBB', 'BBB-', 'BB+', 'BB', 'BB-', 'B+', 'B', 'B-', 'CCC+', 'CCC', 'CCC-']);
  // Every element is a primitive string
  for (const rating of RATING_SCALE) {
    assert.strictEqual(typeof rating, 'string');
    // ASCII + (U+002B) and - (U+002D) only
    assert.match(rating, /^[ABC]{1,3}[+\-]?$/);
  }
});

// AC-2: RATING_SCALE is frozen
test('AC-2: RATING_SCALE is frozen', () => {
  assert.strictEqual(Object.isFrozen(RATING_SCALE), true);

  // In strict mode (ESM is always strict), mutations throw TypeError
  assert.throws(() => {
    RATING_SCALE.push('CC');
  }, TypeError);

  assert.throws(() => {
    RATING_SCALE[0] = 'X';
  }, TypeError);

  assert.throws(() => {
    RATING_SCALE.length = 0;
  }, TypeError);

  assert.throws(() => {
    RATING_SCALE.reverse();
  }, TypeError);

  // After attempted mutations, values remain unchanged
  assert.strictEqual(RATING_SCALE[0], 'AAA');
  assert.strictEqual(RATING_SCALE.length, 19);
  assert.strictEqual(notchChange('AAA', 'CCC-'), 18);
});

// AC-3: notchChange returns number, not Promise; returns +0
test('AC-3: notchChange returns a non-Promise integer', () => {
  const result = notchChange('BBB+', 'BB+');
  assert.strictEqual(result instanceof Promise, false);
  assert.strictEqual(typeof result, 'number');
  assert.strictEqual(Number.isInteger(result), true);

  // Returns +0, not -0
  assert.strictEqual(Object.is(notchChange('A', 'A'), 0), true);
});

// AC-4: Downgrade example
test('AC-4: notchChange(BBB+, BB+) returns 3 (downgrade)', () => {
  assert.strictEqual(notchChange('BBB+', 'BB+'), 3);
});

// AC-5: Upgrade example
test('AC-5: notchChange(BB+, BBB+) returns -3 (upgrade)', () => {
  assert.strictEqual(notchChange('BB+', 'BBB+'), -3);
});

// AC-6: Unchanged example
test('AC-6: notchChange(A, A) returns 0 (unchanged)', () => {
  assert.strictEqual(notchChange('A', 'A'), 0);
});

// AC-7: All 361 pairs
test('AC-7: All 361 pairs follow j - i pattern', () => {
  for (let i = 0; i < 19; i++) {
    for (let j = 0; j < 19; j++) {
      const result = notchChange(RATING_SCALE[i], RATING_SCALE[j]);
      assert.strictEqual(result, j - i, `notchChange(${RATING_SCALE[i]}, ${RATING_SCALE[j]}) should be ${j - i}`);

      // Symmetry: notchChange(a,b) === -notchChange(b,a)
      if (i !== j) {
        const reverse = notchChange(RATING_SCALE[j], RATING_SCALE[i]);
        assert.strictEqual(result, -reverse);
      }
    }
  }
});

// AC-8: Adjacent pairs
test('AC-8: Adjacent pairs return ±1', () => {
  for (let i = 0; i < 18; i++) {
    assert.strictEqual(notchChange(RATING_SCALE[i], RATING_SCALE[i + 1]), 1);
    assert.strictEqual(notchChange(RATING_SCALE[i + 1], RATING_SCALE[i]), -1);
  }
});

// AC-9: Scale ends
test('AC-9: Scale endpoints are 18 notches apart', () => {
  assert.strictEqual(notchChange('AAA', 'CCC-'), 18);
  assert.strictEqual(notchChange('CCC-', 'AAA'), -18);

  // No valid pair returns outside -18..18
  for (let i = 0; i < 19; i++) {
    for (let j = 0; j < 19; j++) {
      const result = notchChange(RATING_SCALE[i], RATING_SCALE[j]);
      assert.ok(result >= -18 && result <= 18);
    }
  }
});

// AC-10: Trim whitespace
test('AC-10: Padded inputs behave like trimmed ratings', () => {
  assert.strictEqual(notchChange(' BBB+ ', 'BB+'), 3);
  assert.strictEqual(notchChange('BB+', '\tBBB+\n'), -3);
  assert.strictEqual(notchChange(' A ', 'A'), 0);

  // NBSP and BOM
  assert.strictEqual(notchChange(' A ', 'A'), 0);
  assert.strictEqual(notchChange('\r\n AAA', 'CCC- ﻿'), 18);
});

// AC-11: Case insensitive
test('AC-11: Case-insensitive matching', () => {
  assert.strictEqual(notchChange('bbb+', 'BBB+'), 0);
  assert.strictEqual(notchChange('bbb+', 'bb+'), 3);
  assert.strictEqual(notchChange('Bb+', ' bBb+ '), -3);
  assert.strictEqual(notchChange('aaa', 'ccc-'), 18);
  assert.strictEqual(notchChange('aA-', 'AA-'), 0);

  // All pairs with case and trim
  for (let i = 0; i < 19; i++) {
    for (let j = 0; j < 19; j++) {
      const result = notchChange(RATING_SCALE[i].toLowerCase(), ' ' + RATING_SCALE[j] + ' ');
      assert.strictEqual(result, j - i);
    }
  }
});

// AC-12: Non-string primitives throw RangeError
test('AC-12: Non-string primitives throw RangeError', () => {
  const nonStrings = [undefined, null, 0, 7, 3.5, NaN, true, false, 1n, Symbol('A')];

  for (const v of nonStrings) {
    assert.throws(() => notchChange(v, 'A'), RangeError, `Failed for notchChange(${String(v)}, 'A')`);
    assert.throws(() => notchChange('A', v), RangeError, `Failed for notchChange('A', ${String(v)})`);
  }

  // Missing arguments
  assert.throws(() => notchChange(), RangeError);
  assert.throws(() => notchChange('A'), RangeError);
});

// AC-13: Objects (including String objects) throw RangeError
test('AC-13: Objects throw RangeError (no coercion)', () => {
  const objects = [
    new String('A'),
    new String('BBB+'),
    ['A'],
    [],
    {},
    { toString() { return 'A'; } },
    Object.create(null),
    () => 'A',
    new Date(0)
  ];

  for (const v of objects) {
    assert.throws(() => notchChange(v, 'A'), RangeError);
    assert.throws(() => notchChange('A', v), RangeError);
  }
});

// AC-14: Empty or whitespace-only strings throw RangeError
test('AC-14: Empty or whitespace-only strings throw RangeError', () => {
  const emptyStrings = ['', ' ', '\t\n', ' '];

  for (const v of emptyStrings) {
    assert.throws(() => notchChange(v, 'A'), RangeError);
    assert.throws(() => notchChange('A', v), RangeError);
  }
});

// AC-15: Unknown ratings throw RangeError
test('AC-15: Unknown ratings throw RangeError', () => {
  const unknownRatings = [
    'CC', 'C', 'D', 'NR', 'SD', 'BBB++', 'AAAA', 'BBB +', 'B B',
    'A−', // Unicode minus
    'A＋', // Fullwidth plus
    'constructor', '__proto__', 'toString'
  ];

  for (const v of unknownRatings) {
    assert.throws(() => notchChange(v, 'A'), RangeError);
    assert.throws(() => notchChange('A', v), RangeError);
  }
});

// AC-16: Both invalid - previous is checked first, never TypeError
test('AC-16: When both invalid, previous is checked first; never TypeError', () => {
  const cases = [
    [Symbol('x'), 42],
    [null, 'CC'],
    ['', Symbol('y')],
    [Object.create(null), new String('A')]
  ];

  for (const [prev, curr] of cases) {
    assert.throws(() => notchChange(prev, curr), RangeError);
  }
});

/**
 * The 19-step credit rating scale, best first.
 * Immutable (frozen). Index 0 is 'AAA', index 7 is 'BBB+', index 10 is 'BB+', index 18 is 'CCC-'.
 */
export const RATING_SCALE = Object.freeze([
  'AAA', 'AA+', 'AA', 'AA-', 'A+', 'A', 'A-',
  'BBB+', 'BBB', 'BBB-',
  'BB+', 'BB', 'BB-',
  'B+', 'B', 'B-',
  'CCC+', 'CCC', 'CCC-'
]);

/**
 * Returns the signed number of notches between two credit ratings.
 * Positive values indicate a downgrade, negative values indicate an upgrade, 0 means unchanged.
 *
 * @param {string} previous - The starting rating (will be trimmed and converted to uppercase)
 * @param {string} current - The ending rating (will be trimmed and converted to uppercase)
 * @returns {number} An integer in the range -18 to 18, where index(current) - index(previous)
 * @throws {RangeError} If either argument is not a string, is empty/whitespace-only, or is not a valid rating.
 *         Previous is validated first. Non-strings are described by typeof; unknown strings by JSON.stringify.
 */
export function notchChange(previous, current) {
  const pIdx = indexOfRating(previous, 'previous');
  const cIdx = indexOfRating(current, 'current');
  return cIdx - pIdx;
}

/**
 * Private helper: validates and finds the index of a rating in RATING_SCALE.
 * @param {*} value - The value to validate and look up
 * @param {string} argName - The name of the argument (for error messages)
 * @returns {number} The index of the rating in RATING_SCALE
 * @throws {RangeError} If value is not a string, is empty/whitespace-only, or is not a valid rating
 */
function indexOfRating(value, argName) {
  if (typeof value !== 'string') {
    throw new RangeError(`${argName} must be a rating string from RATING_SCALE; got type ${typeof value}`);
  }

  const key = value.trim().toUpperCase();
  const idx = RATING_SCALE.indexOf(key);

  if (idx === -1) {
    throw new RangeError(`${argName} must be a rating string from RATING_SCALE; got ${JSON.stringify(value)}`);
  }

  return idx;
}

