2	// Runs one of the kit's bash hooks on every platform:  node run.mjs <hook name>   (stop-guard, bash-guard, …)
3	// Claude Code runs a hook command in the platform shell — on Windows that is cmd/PowerShell, which cannot start a .sh file.
4	// This launcher finds bash (Git Bash on Windows: CLAUDE_CODE_GIT_BASH_PATH, next to git.exe, or the usual install paths),
5	// hands it the hook's stdin and returns its stdout, stderr and exit code unchanged. No bash at all: the hook allows the
6	// action (exit 0) and says so on stderr — a guard that cannot run must not block the user's session.
7	import { spawnSync } from "node:child_process";
8	import { findBash } from "./bash-path.mjs";
9	import { existsSync, readFileSync } from "node:fs";
10	import { dirname, join } from "node:path";
11	import { fileURLToPath } from "node:url";
12	
13	const here = dirname(fileURLToPath(import.meta.url));
14	const name = (process.argv[2] ?? "").replace(/[^a-z-]/g, "");
15	const script = join(here, `${name}.sh`);
16	if (!name || !existsSync(script)) { process.stderr.write(`deliver hook: unknown hook '${process.argv[2] ?? ""}'\n`); process.exit(0); }
17	
18	const bash = findBash();
19	if (!bash) {
20	  process.stderr.write(`deliver hook ${name}: bash not found — install Git for Windows (it brings Git Bash) or set CLAUDE_CODE_GIT_BASH_PATH; the guard did not run\n`);
21	  process.exit(0);
22	}
23	let input = "";
24	try { input = readFileSync(0, "utf8"); } catch { /* no stdin */ }
25	const r = spawnSync(bash, [script], { input, encoding: "utf8", env: process.env, maxBuffer: 16 * 1024 * 1024 });
26	if (r.error) { process.stderr.write(`deliver hook ${name}: ${r.error.message}\n`); process.exit(0); }
27	process.stdout.write(r.stdout ?? ""); process.stderr.write(r.stderr ?? "");
28	process.exit(r.status ?? 0);
